function readStringField(value: unknown, field: string) {
  if (typeof value !== "object" || value === null) {
    return null;
  }

  const candidate = (value as Record<string, unknown>)[field];
  return typeof candidate === "string" ? candidate : null;
}

function serializeTestOpenSourcePhase(phase: OpenSourceCapability["phase"]) {
  return phase === "CurrentMvp" ? "Current" : phase;
}

function normalizeTestOpenSourcePhase(
  phase: "Current" | "CurrentMvp" | "NearTerm" | "LaterPhase" | "all"
) {
  return phase === "CurrentMvp" ? "Current" : phase;
}

function serializeTestOpenSourceCapability(
  capability: OpenSourceCapability
): OpenSourceCapability {
  return {
    ...capability,
    phase: serializeTestOpenSourcePhase(capability.phase)
  };
}

function serializeTestOpenSourceToolCatalogEntry(
  entry: OpenSourceToolCatalogEntry
): OpenSourceToolCatalogEntry {
  return {
    ...entry,
    capabilities: entry.capabilities.map(serializeTestOpenSourceCapability),
    tool: {
      ...entry.tool,
      phase: serializeTestOpenSourcePhase(entry.tool.phase)
    }
  };
}

function buildTestThirdPartyTool(
  entry: OpenSourceToolCatalogEntry,
  override: Partial<ThirdPartyTool["governance"]> = {},
  recentJobs: ToolInstallJob[] = []
): ThirdPartyTool {
  const blocked =
    entry.tool.policyStatus === "RequiresLegalReview" ||
    entry.executionReadiness === "Blocked" ||
    entry.readiness === "Blocked";
  const status = blocked
    ? entry.tool.policyStatus === "RequiresLegalReview"
      ? "LegalReviewRequired"
      : "Blocked"
    : "Enabled";
  const now = new Date().toISOString();

  return {
    governance: {
      allowedRuntimes: entry.tool.runtimePreference,
      disabledReason: blocked ? "Blocked by governance policy." : null,
      enabled: !blocked,
      legalReviewStatus:
        entry.tool.policyStatus === "RequiresLegalReview"
          ? "RequiresLegalReview"
          : blocked
            ? "Blocked"
            : "Approved",
      pinnedGitRef: entry.tool.gitRepo ? entry.tool.defaultVersion : null,
      pinnedImageRef: entry.tool.dockerImage
        ? `${entry.tool.dockerImage}:${entry.tool.defaultVersion}`
        : null,
      pinnedVersion: entry.tool.defaultVersion,
      source: "Default",
      status,
      tenantId: null,
      toolId: entry.tool.toolId,
      updatedAt: now,
      ...override
    },
    recentJobs,
    runtimeInstallation: {
      installedAt: null,
      installedVersion: null,
      installStatus: entry.runtimeAvailable
        ? "Available"
        : blocked
          ? "Skipped"
          : "Missing",
      lastCheckedAt: entry.lastCheckedAt ?? null,
      runtimeAvailable: Boolean(entry.runtimeAvailable),
      runtimeKind: entry.runtimeKind ?? null,
      runtimeReason:
        entry.runtimeReason ?? "Runtime readiness has not been checked.",
      toolId: entry.tool.toolId
    },
    tool: entry
  };
}

const testRunnerInternalCheckModuleIds =
  RunnerInternalCheckModuleSchema.options;
const testServerRunnerAllowlistedModuleIds = [
  ...new Set([
    ...RUNNER_DISCOVER_MODULE_IDS,
    ...RUNNER_MEASURED_MODULE_IDS,
    ...testRunnerInternalCheckModuleIds
  ])
];
const testServerRunnerAllowlistedModuleIdSet = new Set<string>(
  testServerRunnerAllowlistedModuleIds
);

function getTestRunnerDispatchRoute(moduleId: string | null | undefined) {
  if (!moduleId || !testServerRunnerAllowlistedModuleIdSet.has(moduleId)) {
    return null;
  }

  if ((RUNNER_DISCOVER_MODULE_IDS as readonly string[]).includes(moduleId)) {
    return "/api/v1/runners/:runnerId/tasks/discover";
  }

  if ((RUNNER_MEASURED_MODULE_IDS as readonly string[]).includes(moduleId)) {
    return "/api/v1/runners/:runnerId/tasks/measured";
  }

  return "/api/v1/runners/:runnerId/tasks/check";
}

function testRunnerStatusPriority(status: ToolRunnerEligibilityStatus) {
  const priority: Record<ToolRunnerEligibilityStatus, number> = {
    Blocked: 90,
    RequiresEnablement: 80,
    NeedsImplementation: 70,
    RequiresRuntime: 60,
    RequiresRunner: 50,
    RequiresVerifiedScope: 40,
    RequiresApproval: 30,
    FixtureOnly: 20,
    ControlPlaneOnly: 10,
    Ready: 0
  };

  return priority[status];
}

function selectTestRunnerStatus(
  statuses: ToolRunnerEligibilityStatus[]
): ToolRunnerEligibilityStatus {
  if (!statuses.length) {
    return "ControlPlaneOnly";
  }

  if (statuses.includes("Ready")) {
    return "Ready";
  }

  const selected = [...statuses].sort(
    (left, right) =>
      testRunnerStatusPriority(right) - testRunnerStatusPriority(left)
  )[0];
  return selected ?? "ControlPlaneOnly";
}

function buildTestThirdPartyToolRunnerEligibility(input: {
  activeRunnerCount: number;
  tenantId: string;
  tool: ThirdPartyTool;
  verifiedScopeCount: number;
  verifiedScopeTypes: ScopeType[];
}): ThirdPartyToolRunnerEligibility {
  const capabilities: ToolRunnerCapabilityEligibility[] =
    input.tool.tool.capabilities.map((capability) => {
      const dispatchRoute = getTestRunnerDispatchRoute(capability.moduleId);
      const reasons: string[] = [];
      const requiredActions: string[] = [];
      const hasCompatibleVerifiedScope =
        capability.requiredScopes.length === 0 ||
        capability.requiredScopes.some((scopeType) =>
          input.verifiedScopeTypes.includes(scopeType)
        );
      let status: ToolRunnerEligibilityStatus = "Ready";

      if (capability.executionMode !== "InternalRunner") {
        status = "ControlPlaneOnly";
        reasons.push(
          `Capability executes through ${capability.executionMode}, not the internal runner.`
        );
      } else if (
        input.tool.governance.status === "Blocked" ||
        input.tool.governance.status === "LegalReviewRequired" ||
        capability.status === "BlockedLegalReview" ||
        capability.safetyLevels.includes("AdvancedAdversarial")
      ) {
        status = "Blocked";
        reasons.push(
          "Capability is blocked by legal review, safety policy, or advanced-adversarial restrictions."
        );
        requiredActions.push(
          "Complete documented legal and safety review before runner execution can be considered."
        );
      } else if (
        !input.tool.governance.enabled ||
        input.tool.governance.status !== "Enabled"
      ) {
        status = "RequiresEnablement";
        reasons.push("Tenant governance has disabled this tool.");
        requiredActions.push(
          "Enable the tool for this tenant before runner use."
        );
      } else if (capability.status === "FixtureOnly") {
        status = "FixtureOnly";
        reasons.push("Capability is fixture-only and cannot execute live.");
        requiredActions.push(
          "Implement and validate the live runner execution path before dispatch."
        );
      } else if (capability.status !== "Implemented" || !dispatchRoute) {
        status = "NeedsImplementation";
        reasons.push(
          dispatchRoute
            ? "Capability is not implemented for live runner dispatch."
            : "Capability module is not in the server-side runner dispatch allowlist."
        );
        requiredActions.push(
          "Add a reviewed module manifest, parser tests, local runner allowlist entry, and signed-task API route before dispatch."
        );
      } else if (!input.tool.runtimeInstallation.runtimeAvailable) {
        status = "RequiresRuntime";
        reasons.push("Required tool runtime is not available.");
        requiredActions.push(
          "Check or install the reviewed runtime through Third-Party Tool Governance."
        );
      } else if (input.activeRunnerCount === 0) {
        status = "RequiresRunner";
        reasons.push(
          "No active internal runner is registered for this tenant."
        );
        requiredActions.push(
          "Register and activate an outbound-only internal runner before dispatch."
        );
      } else if (
        capability.requiredScopes.length > 0 &&
        !hasCompatibleVerifiedScope
      ) {
        status = "RequiresVerifiedScope";
        reasons.push(
          "No verified tenant scope matches this runner capability."
        );
        requiredActions.push(
          `Verify one of these scope types before dispatch: ${capability.requiredScopes.join(", ")}.`
        );
      } else if (
        capability.safetyLevels.includes("ControlledValidation") ||
        capability.safetyLevels.includes("BASLite")
      ) {
        status = "RequiresApproval";
        reasons.push(
          "Capability requires explicit approval before a runner task can be created."
        );
        requiredActions.push(
          "Create a policy-approved mission or approval state before runner dispatch."
        );
      } else {
        reasons.push("Capability is server-allowlisted for runner dispatch.");
      }

      return {
        capabilityId: capability.capabilityId,
        dispatchRoute,
        dispatchable: status === "Ready",
        executionMode: capability.executionMode,
        moduleId: capability.moduleId,
        name: capability.name,
        reasons,
        requiredActions,
        requiredScopes: capability.requiredScopes,
        safetyLevels: capability.safetyLevels,
        status
      };
    });
  const runnerCapabilities = capabilities.filter(
    (capability) => capability.executionMode === "InternalRunner"
  );
  const status = selectTestRunnerStatus(
    runnerCapabilities.map((capability) => capability.status)
  );
  const eligible = runnerCapabilities.some(
    (capability) => capability.dispatchable
  );
  const unique = (values: string[]) => [...new Set(values.filter(Boolean))];

  return {
    activeRunnerCount: input.activeRunnerCount,
    capabilities,
    eligible,
    generatedAt: now(),
    governanceStatus: input.tool.governance.status,
    reasons: eligible
      ? ["At least one capability is ready for runner dispatch."]
      : runnerCapabilities.length === 0
        ? [
            "This tool has no InternalRunner capability in the reviewed catalog."
          ]
        : unique(
            runnerCapabilities.flatMap((capability) => capability.reasons)
          ),
    requiredActions: unique(
      runnerCapabilities.flatMap((capability) => capability.requiredActions)
    ),
    runtimeAvailable: input.tool.runtimeInstallation.runtimeAvailable,
    runtimeKind: input.tool.runtimeInstallation.runtimeKind,
    serverAllowlistedModuleIds: testServerRunnerAllowlistedModuleIds,
    status,
    tenantId: input.tenantId,
    toolId: input.tool.tool.tool.toolId,
    verifiedScopeCount: input.verifiedScopeCount
  };
}

async function buildTestThirdPartyToolCandidateReadinessAsync(
  candidate: ThirdPartyToolCandidate
): Promise<ThirdPartyToolCandidateReadiness> {
  const entries = await listOpenSourceToolCatalogWithRuntime({
    includeDeferred: true,
    includeLegalReview: true,
    phase: "all"
  });
  const catalogEntry =
    entries.find((entry) => entry.tool.toolId === candidate.toolId) ?? null;
  const moduleManifest = listModuleManifests().find(
    (manifest) => manifest.moduleId === candidate.manifest.moduleId
  );
  const moduleDeclaresTool =
    moduleManifest?.toolIds.some((toolId) => toolId === candidate.toolId) ??
    false;
  const checks: ThirdPartyToolCandidateReadiness["checks"] = [
    {
      checkId: "intake-decision",
      evidence: [`Candidate status is ${candidate.status}.`],
      requiredAction:
        candidate.status === "AcceptedForCatalogReview"
          ? null
          : "Resolve intake report findings before platform review.",
      status:
        candidate.status === "AcceptedForCatalogReview"
          ? "Satisfied"
          : candidate.status === "Rejected"
            ? "Blocked"
            : "ActionRequired",
      summary:
        candidate.status === "AcceptedForCatalogReview"
          ? "The candidate passed automated intake checks for review."
          : candidate.validationReport.summary,
      title: "Intake certification"
    },
    {
      checkId: "catalog-entry",
      evidence: catalogEntry
        ? [`Reviewed catalog entry exists for ${candidate.toolId}.`]
        : [
            `Candidate tool ID ${candidate.toolId} is not in the reviewed catalog.`
          ],
      requiredAction: catalogEntry
        ? null
        : "Add a reviewed OSS tool catalog entry before tenant governance can manage this tool.",
      status: catalogEntry ? "Satisfied" : "Missing",
      summary: catalogEntry
        ? "The tool is present in the reviewed OSS catalog."
        : "No reviewed catalog entry exists yet.",
      title: "Reviewed catalog entry"
    },
    {
      checkId: "module-manifest",
      evidence: moduleManifest
        ? [`Module manifest ${moduleManifest.moduleId} exists.`]
        : [`Module manifest ${candidate.manifest.moduleId} is not registered.`],
      requiredAction: moduleManifest
        ? null
        : "Implement and register the validation module manifest, parser, fixtures, and tests.",
      status: moduleManifest ? "Satisfied" : "Missing",
      summary: moduleManifest
        ? "The requested module manifest is registered."
        : "No registered module manifest exists for this candidate.",
      title: "Module manifest"
    },
    {
      checkId: "module-tool-binding",
      evidence: moduleManifest
        ? [
            moduleDeclaresTool
              ? `Module ${moduleManifest.moduleId} declares tool ${candidate.toolId}.`
              : `Module ${moduleManifest.moduleId} does not declare tool ${candidate.toolId}.`
          ]
        : ["Tool binding cannot be checked until the module manifest exists."],
      requiredAction: moduleDeclaresTool
        ? null
        : "Bind the reviewed tool ID to the module manifest after adding it to the shared tool ID contract.",
      status: moduleManifest
        ? moduleDeclaresTool
          ? "Satisfied"
          : "ActionRequired"
        : "Missing",
      summary: moduleDeclaresTool
        ? "The module/tool relationship is declared."
        : "The module is not yet bound to the proposed tool ID.",
      title: "Module to tool binding"
    },
    {
      checkId: "governance-policy",
      evidence: catalogEntry
        ? [
            "A governance policy can be composed from the reviewed catalog entry."
          ]
        : [
            "Governance policies are only available for reviewed catalog tools."
          ],
      requiredAction: catalogEntry
        ? null
        : "Promote the reviewed catalog entry before enabling, disabling, checking, or installing the tool.",
      status: catalogEntry ? "Satisfied" : "Missing",
      summary: catalogEntry
        ? "The tool can use tenant governance policy."
        : "Tenant governance is unavailable until catalog promotion.",
      title: "Governance policy surface"
    }
  ];
  const status = checks.some((check) => check.status === "Blocked")
    ? "Blocked"
    : checks.some((check) => check.status !== "Satisfied")
      ? "NeedsImplementation"
      : "ReadyForGovernance";

  return {
    candidateId: candidate.candidateId,
    catalogEntryPresent: Boolean(catalogEntry),
    checks,
    displayName: candidate.displayName,
    generatedAt: now(),
    governancePolicyAvailable: Boolean(catalogEntry),
    moduleManifestPresent: Boolean(moduleManifest),
    readyForGovernance: status === "ReadyForGovernance",
    requiredActions: [
      ...new Set([
        ...candidate.validationReport.requiredActions,
        ...checks
          .map((check) => check.requiredAction)
          .filter((action): action is string => Boolean(action))
      ])
    ],
    status,
    tenantId: candidate.tenantId,
    toolId: candidate.toolId
  };
}

async function buildTestThirdPartyToolImplementationWorkOrder(
  candidate: ThirdPartyToolCandidate,
  generatedBy: string | null
): Promise<ThirdPartyToolImplementationWorkOrder> {
  const readiness =
    await buildTestThirdPartyToolCandidateReadinessAsync(candidate);
  const generatedAt = now();
  const status =
    readiness.status === "Blocked"
      ? "Blocked"
      : readiness.readyForGovernance
        ? "ReadyForImplementation"
        : "Draft";

  return {
    candidateId: candidate.candidateId,
    createdAt: generatedAt,
    displayName: candidate.displayName,
    generatedBy,
    readinessStatus: readiness.status,
    requiredActions: readiness.requiredActions,
    reviewStatus: candidate.reviewStatus,
    scaffoldFiles: [
      {
        contentPreview: `moduleId: ${candidate.manifest.moduleId}`,
        path: `packages/modules/src/${candidate.toolId}.ts`,
        purpose: "Validation module manifest, executor, and parser wrapper",
        templateKind: "ModuleManifest"
      },
      {
        contentPreview: `${candidate.displayName} (${candidate.manifest.license})`,
        path: "licenses/THIRD_PARTY_NOTICES.md",
        purpose: "License inventory and third-party notice update",
        templateKind: "LicenseNotice"
      }
    ],
    status,
    summary:
      status === "ReadyForImplementation"
        ? `${candidate.displayName} has the required reviewed surfaces and can move into implementation verification.`
        : `${candidate.displayName} needs ${readiness.requiredActions.length} implementation action(s) before governance promotion or execution.`,
    tasks: [
      {
        blocksExecution: true,
        category: "ModuleManifest",
        description:
          "Implement the validation module manifest and bind it to the reviewed tool ID.",
        requiredEvidence: [
          `Module manifest ${candidate.manifest.moduleId} exists`,
          `Module declares tool ${candidate.toolId}`
        ],
        status: "NotStarted",
        taskId: "module-manifest",
        title: "Create module manifest and tool binding"
      },
      {
        blocksExecution: true,
        category: "Policy",
        description:
          "Add policy tests proving the module respects scope verification, approval, disabled-tool, and legal-review gates.",
        requiredEvidence: [
          "Policy denial test",
          "Disabled-tool mission denial test"
        ],
        status: "NotStarted",
        taskId: "policy-gates",
        title: "Certify policy and safety gates"
      }
    ],
    tenantId: candidate.tenantId,
    toolId: candidate.toolId,
    updatedAt: generatedAt,
    workOrderId: randomUUID()
  };
}

function buildTestThirdPartyToolImplementationBundle(
  candidate: ThirdPartyToolCandidate,
  workOrder: ThirdPartyToolImplementationWorkOrder
): ThirdPartyToolImplementationBundle {
  const files = workOrder.scaffoldFiles.map((file) => {
    const content = [
      "# Periscan implementation scaffold",
      `# Tool: ${candidate.displayName} (${candidate.toolId})`,
      `# Work order: ${workOrder.workOrderId}`,
      `# Template: ${file.templateKind}`,
      `# Purpose: ${file.purpose}`,
      "",
      file.contentPreview
    ].join("\n");

    return {
      content,
      contentSha256: createHash("sha256").update(content).digest("hex"),
      path: file.path,
      purpose: file.purpose,
      templateKind: file.templateKind
    };
  });

  return {
    bundleId: `tool-implementation-bundle:${workOrder.workOrderId}`,
    candidateId: candidate.candidateId,
    commands: [
      "pnpm --filter @periscan/modules test",
      "pnpm test:modules -- module-certification",
      "pnpm lint",
      "pnpm typecheck"
    ],
    displayName: candidate.displayName,
    doesNotExecute: true,
    files,
    generatedAt: now(),
    readinessStatus: workOrder.readinessStatus,
    requiredActions: workOrder.requiredActions,
    reviewStatus: workOrder.reviewStatus,
    safetyNotes: [
      "Implementation bundles are scaffold artifacts only and do not install, enable, queue, dispatch, or execute tools."
    ],
    status: workOrder.status === "Blocked" ? "Blocked" : "ReadyForDownload",
    summary: `${candidate.displayName} implementation bundle contains ${files.length} scaffold file(s).`,
    tenantId: candidate.tenantId,
    toolId: candidate.toolId,
    workOrderId: workOrder.workOrderId
  };
}

async function buildTestThirdPartyToolPromotionPackage(
  candidate: ThirdPartyToolCandidate,
  promotedBy: string | null
): Promise<ThirdPartyToolPromotionPackage> {
  const entry = await getOpenSourceToolCatalogEntryWithRuntime(
    candidate.toolId as OpenSourceToolId
  );
  const readiness =
    await buildTestThirdPartyToolCandidateReadinessAsync(candidate);

  if (!entry || !readiness.readyForGovernance) {
    throw new AppServiceError(
      "Candidate cannot generate a promotion package until reviewed catalog, module, governance, runner, and safety checks are satisfied.",
      409,
      "third_party_tool_candidate_not_ready"
    );
  }

  const timestamp = now();

  return {
    capabilityIds: entry.capabilities.map(
      (capability) => capability.capabilityId
    ),
    candidateId: candidate.candidateId,
    catalogSnapshot: entry,
    createdAt: timestamp,
    displayName: candidate.displayName,
    governanceSnapshot: {
      allowedRuntimes: entry.tool.runtimePreference,
      disabledReason: null,
      enabled: true,
      legalReviewStatus: "Approved",
      pinnedGitRef: entry.tool.gitRepo ? entry.tool.defaultVersion : null,
      pinnedImageRef: entry.tool.dockerImage
        ? `${entry.tool.dockerImage}:${entry.tool.defaultVersion}`
        : null,
      pinnedVersion: entry.tool.defaultVersion,
      source: "Default",
      status: "Enabled",
      tenantId: candidate.tenantId,
      toolId: entry.tool.toolId,
      updatedAt: timestamp
    },
    implementationOwner: candidate.implementationOwner,
    moduleIds: [
      ...new Set([
        ...entry.tool.moduleIds,
        ...entry.capabilities
          .map((capability) => capability.moduleId)
          .filter((moduleId): moduleId is string => Boolean(moduleId))
      ])
    ],
    promotedAt: timestamp,
    promotedBy,
    promotionPackageId: randomUUID(),
    readinessReport: readiness,
    requiredEvidence: [
      "Reviewed catalog entry exists for the tool.",
      "Registered module manifest declares the promoted tool ID.",
      "Tenant/global governance policy is available.",
      ...readiness.checks.flatMap((check) => check.evidence)
    ],
    reviewStatus: candidate.reviewStatus,
    runtimeInstallation: {
      installedAt: null,
      installedVersion: null,
      installStatus: entry.runtimeAvailable ? "Available" : "Missing",
      lastCheckedAt: entry.lastCheckedAt ?? null,
      runtimeAvailable: Boolean(entry.runtimeAvailable),
      runtimeKind: entry.runtimeKind ?? null,
      runtimeReason: entry.runtimeReason ?? "Runtime readiness is tracked.",
      toolId: entry.tool.toolId
    },
    safetyNotes: [
      "Promotion packages are non-executing governance artifacts.",
      "Execution remains gated by tenant enablement, verified scope, policy decisions, runtime readiness, and runner/task allowlists."
    ],
    status: "ReadyForGovernance",
    summary: `${candidate.displayName} has reviewed catalog, module, governance, runtime, and safety evidence captured for governed enablement.`,
    tenantId: candidate.tenantId,
    toolId: entry.tool.toolId,
    updatedAt: timestamp
  };
}

function buildTestThirdPartyToolPromotionHandoff(input: {
  promotionPackage: ThirdPartyToolPromotionPackage;
  runnerEligibility: ThirdPartyToolRunnerEligibility;
  tool: ThirdPartyTool;
}): ThirdPartyToolPromotionHandoff {
  const packageReady =
    input.promotionPackage.status === "ReadyForGovernance" &&
    input.promotionPackage.readinessReport.readyForGovernance;
  const governanceBlocked =
    input.tool.governance.status === "Blocked" ||
    input.tool.governance.status === "LegalReviewRequired";
  const governanceEnabled =
    input.tool.governance.enabled && input.tool.governance.status === "Enabled";
  const runtimeAvailable = input.tool.runtimeInstallation.runtimeAvailable;
  const hasRunnerCapability = input.tool.tool.capabilities.some(
    (capability) => capability.executionMode === "InternalRunner"
  );
  const hasMissionCapability = input.tool.tool.capabilities.some(
    (capability) =>
      capability.status === "Implemented" &&
      capability.executionMode !== "InternalRunner"
  );
  const runnerReady =
    input.runnerEligibility.status === "Ready" ||
    input.runnerEligibility.status === "ControlPlaneOnly";
  const status =
    !packageReady || governanceBlocked
      ? "Blocked"
      : !governanceEnabled
        ? "ReadyForGovernanceAction"
        : !runtimeAvailable
          ? "NeedsRuntimeAction"
          : hasRunnerCapability && !runnerReady
            ? "NeedsRunnerPrerequisite"
            : "ReadyForPolicyApproval";

  return {
    actions: [
      {
        actionId: "enable-tool",
        apiMethod: "POST",
        apiPath: `/api/v1/third-party-tools/${input.promotionPackage.toolId}/enable`,
        blockedBy: governanceBlocked
          ? [
              "Tenant governance is blocked by legal review or platform safety policy."
            ]
          : [],
        createsExecution: false,
        kind: "EnableTool",
        policyGateRequired: false,
        reasons: governanceEnabled
          ? ["Tenant governance already enables this reviewed tool."]
          : [],
        requiredActions: governanceEnabled
          ? []
          : ["Call the enable endpoint with an operator reason."],
        status:
          !packageReady || governanceBlocked
            ? "Blocked"
            : governanceEnabled
              ? "AlreadySatisfied"
              : "Ready",
        summary: governanceEnabled
          ? "Tool is enabled for this tenant."
          : "Enable the reviewed tool before missions or runner dispatch use it.",
        title: "Enable tenant governance"
      },
      {
        actionId: "check-runtime",
        apiMethod: "POST",
        apiPath: `/api/v1/third-party-tools/${input.promotionPackage.toolId}/check`,
        blockedBy: [],
        createsExecution: false,
        kind: "CheckRuntime",
        policyGateRequired: false,
        reasons: [input.tool.runtimeInstallation.runtimeReason],
        requiredActions: runtimeAvailable
          ? []
          : ["Run a governed runtime readiness check."],
        status: runtimeAvailable ? "AlreadySatisfied" : "Ready",
        summary: runtimeAvailable
          ? "Runtime is available according to current governance state."
          : "Check the reviewed runtime before using this tool.",
        title: "Check runtime readiness"
      },
      {
        actionId: "install-runtime",
        apiMethod: "POST",
        apiPath: `/api/v1/third-party-tools/${input.promotionPackage.toolId}/install`,
        blockedBy: [],
        createsExecution: false,
        kind: "InstallRuntime",
        policyGateRequired: false,
        reasons: [
          `Allowed install runtimes: ${input.tool.governance.allowedRuntimes.join(", ")}.`
        ],
        requiredActions: runtimeAvailable
          ? []
          : ["Queue a governed install job."],
        status: runtimeAvailable ? "AlreadySatisfied" : "Ready",
        summary: runtimeAvailable
          ? "No install job is needed before use."
          : "Queue an install job only for reviewed runtime artifacts.",
        title: "Install reviewed runtime"
      },
      {
        actionId: "check-runner-eligibility",
        apiMethod: hasRunnerCapability ? "GET" : null,
        apiPath: hasRunnerCapability
          ? `/api/v1/third-party-tools/${input.promotionPackage.toolId}/runner-eligibility`
          : null,
        blockedBy: [],
        createsExecution: false,
        kind: "CheckRunnerEligibility",
        policyGateRequired: false,
        reasons: hasRunnerCapability
          ? input.runnerEligibility.reasons
          : ["This promoted tool has no InternalRunner capabilities."],
        requiredActions: hasRunnerCapability
          ? input.runnerEligibility.requiredActions
          : [],
        status: hasRunnerCapability
          ? input.runnerEligibility.status === "Ready"
            ? "AlreadySatisfied"
            : "Ready"
          : "NotApplicable",
        summary: hasRunnerCapability
          ? "Read current customer-network runner prerequisites before dispatch."
          : "Runner readiness is not required for this tool.",
        title: "Check internal runner eligibility"
      },
      {
        actionId: "dispatch-runner-capability",
        apiMethod: hasRunnerCapability ? "POST" : null,
        apiPath: hasRunnerCapability
          ? `/api/v1/third-party-tools/${input.promotionPackage.toolId}/runner-dispatch`
          : null,
        blockedBy: [],
        createsExecution: true,
        kind: "DispatchRunnerCapability",
        policyGateRequired: true,
        reasons: input.runnerEligibility.reasons,
        requiredActions: input.runnerEligibility.requiredActions,
        status: !hasRunnerCapability
          ? "NotApplicable"
          : input.runnerEligibility.eligible
            ? "Ready"
            : "NeedsAction",
        summary: hasRunnerCapability
          ? "Dispatch only after runner eligibility is ready and target is verified."
          : "Runner dispatch is not part of this tool's reviewed execution path.",
        title: "Dispatch runner capability"
      },
      {
        actionId: "start-policy-gated-mission",
        apiMethod: hasMissionCapability ? "POST" : null,
        apiPath: hasMissionCapability ? "/api/v1/missions" : null,
        blockedBy: [],
        createsExecution: true,
        kind: "StartMission",
        policyGateRequired: true,
        reasons: [
          "Mission start remains subject to verified scope, policy decision, tenant tool enablement, runtime readiness, and module safety gates."
        ],
        requiredActions:
          packageReady &&
          governanceEnabled &&
          runtimeAvailable &&
          hasMissionCapability
            ? [
                "Create or start a mission using the reviewed module; policy approval is still evaluated before queueing."
              ]
            : [
                "Resolve package, governance, runtime, or module prerequisites."
              ],
        status:
          packageReady &&
          governanceEnabled &&
          runtimeAvailable &&
          hasMissionCapability
            ? "Ready"
            : "NeedsAction",
        summary: hasMissionCapability
          ? "Use the existing mission APIs to execute reviewed modules under policy."
          : "Mission execution is unavailable until a reviewed module supports it.",
        title: "Start policy-gated validation mission"
      }
    ],
    candidateId: input.promotionPackage.candidateId,
    generatedAt: now(),
    governanceEnabled,
    governanceStatus: input.tool.governance.status,
    promotionPackageId: input.promotionPackage.promotionPackageId,
    runnerEligibility: input.runnerEligibility,
    runtimeAvailable,
    runtimeStatus: input.tool.runtimeInstallation.installStatus,
    status,
    summary:
      status === "ReadyForPolicyApproval"
        ? `${input.promotionPackage.displayName} is ready for explicit policy-gated mission or runner approval.`
        : `${input.promotionPackage.displayName} has open governance handoff prerequisites.`,
    tenantId: input.promotionPackage.tenantId,
    toolId: input.promotionPackage.toolId
  };
}

function buildTestThirdPartyToolPromotionCertification(input: {
  handoff: ThirdPartyToolPromotionHandoff;
  promotionPackage: ThirdPartyToolPromotionPackage;
  runnerEligibility: ThirdPartyToolRunnerEligibility;
  tool: ThirdPartyTool;
}): ThirdPartyToolPromotionCertification {
  const packageReady =
    input.promotionPackage.status === "ReadyForGovernance" &&
    input.promotionPackage.readinessReport.readyForGovernance;
  const governanceBlocked =
    input.tool.governance.status === "Blocked" ||
    input.tool.governance.status === "LegalReviewRequired";
  const governanceEnabled =
    input.tool.governance.enabled && input.tool.governance.status === "Enabled";
  const runtimeAvailable = input.tool.runtimeInstallation.runtimeAvailable;
  const hasRunnerCapability = input.tool.tool.capabilities.some(
    (capability) => capability.executionMode === "InternalRunner"
  );
  const hasMissionCapability = input.tool.tool.capabilities.some(
    (capability) =>
      capability.status === "Implemented" &&
      capability.executionMode !== "InternalRunner"
  );
  const executionActions = input.handoff.actions.filter(
    (action) => action.createsExecution
  );
  const executionGateBypass = executionActions.some(
    (action) => !action.policyGateRequired
  );
  const checks: ThirdPartyToolPromotionCertification["checks"] = [
    {
      category: "Catalog",
      checkId: "promotion-package",
      evidence: [
        `Promotion package status is ${input.promotionPackage.status}.`
      ],
      requiredActions: packageReady
        ? []
        : input.promotionPackage.readinessReport.requiredActions,
      status: packageReady ? "Passed" : "Blocked",
      summary: packageReady
        ? "Promotion package is readiness-satisfied."
        : "Promotion package is not ready for governance or execution decisions.",
      title: "Promotion package"
    },
    {
      category: "Governance",
      checkId: "tenant-governance",
      evidence: [
        `Governance status is ${input.tool.governance.status}.`,
        `Governance enabled: ${input.tool.governance.enabled}.`
      ],
      requiredActions: governanceEnabled
        ? []
        : ["Enable the reviewed tool for this tenant before use."],
      status: governanceBlocked
        ? "Blocked"
        : governanceEnabled
          ? "Passed"
          : "NeedsAction",
      summary: governanceEnabled
        ? "Tenant governance enables this reviewed tool."
        : "Tenant governance is not yet ready for use.",
      title: "Tenant governance"
    },
    {
      category: "Runtime",
      checkId: "runtime-readiness",
      evidence: [
        `Runtime status is ${input.tool.runtimeInstallation.installStatus}.`
      ],
      requiredActions: runtimeAvailable
        ? []
        : ["Check or install an allowlisted runtime before execution."],
      status: runtimeAvailable ? "Passed" : "NeedsAction",
      summary: runtimeAvailable
        ? "Runtime readiness is currently satisfied."
        : "Runtime readiness is not currently satisfied.",
      title: "Runtime readiness"
    },
    {
      category: "Runner",
      checkId: "runner-readiness",
      evidence: hasRunnerCapability
        ? [`Runner eligibility status is ${input.runnerEligibility.status}.`]
        : ["No InternalRunner capabilities exist for this tool."],
      requiredActions: hasRunnerCapability
        ? input.runnerEligibility.requiredActions
        : [],
      status: hasRunnerCapability
        ? input.runnerEligibility.status === "Ready" ||
          input.runnerEligibility.status === "ControlPlaneOnly"
          ? "Passed"
          : "NeedsAction"
        : "NotApplicable",
      summary: hasRunnerCapability
        ? "Runner prerequisites are evaluated from current tenant state."
        : "Runner dispatch is not required for this promoted tool.",
      title: "Internal runner readiness"
    },
    {
      category: "Policy",
      checkId: "execution-policy-gates",
      evidence: [
        `${executionActions.length} execution-creating action(s) evaluated.`
      ],
      requiredActions: executionGateBypass
        ? ["Ensure every execution-creating action requires policy approval."]
        : [],
      status: executionGateBypass ? "Blocked" : "Passed",
      summary: executionGateBypass
        ? "At least one execution action would bypass policy gates."
        : "Execution actions remain policy-gated and are not performed by this report.",
      title: "Execution policy gates"
    }
  ];
  const requiredActions = [
    ...new Set(checks.flatMap((check) => check.requiredActions))
  ];
  const hasBlocked = checks.some((check) => check.status === "Blocked");
  const hasNeedsAction = checks.some((check) => check.status === "NeedsAction");
  const status = hasBlocked
    ? "Blocked"
    : hasNeedsAction
      ? "NeedsAction"
      : "CertifiedForUse";

  return {
    candidateId: input.promotionPackage.candidateId,
    certificationId: `tool-promotion-certification:${input.promotionPackage.promotionPackageId}`,
    certifiedForGovernance: packageReady && !governanceBlocked,
    certifiedForMissionStart:
      packageReady &&
      governanceEnabled &&
      runtimeAvailable &&
      hasMissionCapability &&
      !executionGateBypass,
    certifiedForRuntimeManagement:
      packageReady && input.tool.governance.allowedRuntimes.length > 0,
    certifiedForRunnerDispatch: false,
    checks,
    displayName: input.promotionPackage.displayName,
    doesNotDispatchRunnerTasks: true,
    doesNotEnable: true,
    doesNotExecute: true,
    doesNotInstall: true,
    doesNotQueueMissions: true,
    generatedAt: now(),
    governanceStatus: input.tool.governance.status,
    packageStatus: input.promotionPackage.status,
    promotionPackageId: input.promotionPackage.promotionPackageId,
    readinessStatus: input.promotionPackage.readinessReport.status,
    requiredActions,
    runnerStatus: input.runnerEligibility.status,
    runtimeStatus: input.tool.runtimeInstallation.installStatus,
    safetyNotes: [
      ...input.promotionPackage.safetyNotes,
      "Certification reports are read-only and do not enable, install, queue, dispatch, or execute tools."
    ],
    status,
    summary:
      status === "CertifiedForUse"
        ? `${input.promotionPackage.displayName} is certified for policy-gated use from current governance state.`
        : `${input.promotionPackage.displayName} has open certification prerequisites.`,
    tenantId: input.promotionPackage.tenantId,
    toolId: input.promotionPackage.toolId
  };
}

function buildTestThirdPartyToolUpdateRecommendation(input: {
  generatedBy: string | null;
  installedVersion?: string | null;
  pinnedVersion: string;
  reviewedVersion: string;
  runtimeKind?: ThirdPartyToolUpdateRecommendation["runtimeKind"];
  status?: ThirdPartyToolUpdateRecommendation["status"];
  tenantId: string;
  toolId: OpenSourceToolId;
}): ThirdPartyToolUpdateRecommendation {
  const timestamp = now();
  const status =
    input.status ??
    (input.pinnedVersion === input.reviewedVersion
      ? "UpToDate"
      : "UpdateAvailable");

  return {
    appliedAt: null,
    appliedBy: null,
    createdAt: timestamp,
    currentInstalledVersion: input.installedVersion ?? null,
    currentPinnedVersion: input.pinnedVersion,
    dismissedAt: null,
    dismissedBy: null,
    generatedAt: timestamp,
    generatedBy: input.generatedBy,
    installJobId: null,
    policyBlocked: status === "Blocked",
    reason:
      status === "UpdateAvailable"
        ? `Reviewed catalog version ${input.reviewedVersion} differs from pinned version ${input.pinnedVersion}.`
        : `Tool is pinned to reviewed catalog version ${input.reviewedVersion}.`,
    recommendationId: randomUUID(),
    requiredActions:
      status === "UpdateAvailable"
        ? ["Apply the reviewed pin", "Queue an install job before runtime use"]
        : ["No tool version update is required"],
    reviewedVersion: input.reviewedVersion,
    runtimeKind: input.runtimeKind ?? "docker",
    source: "ReviewedCatalog",
    status,
    tenantId: input.tenantId,
    toolId: input.toolId,
    updatedAt: timestamp
  };
}

function buildTestThirdPartyToolUpstreamVersionCheck(input: {
  catalogVersion: string;
  checkedBy: string | null;
  discoveredVersion?: string | null;
  status?: ThirdPartyToolUpstreamVersionCheck["status"];
  tenantId: string;
  toolId: OpenSourceToolId;
}): ThirdPartyToolUpstreamVersionCheck {
  const timestamp = now();
  const discoveredVersion = input.discoveredVersion ?? null;
  const status =
    input.status ??
    (discoveredVersion && discoveredVersion !== input.catalogVersion
      ? "CandidateAvailable"
      : "UpToDate");

  return {
    catalogVersion: input.catalogVersion,
    checkedAt: timestamp,
    checkedBy: input.checkedBy,
    checkId: randomUUID(),
    discoveredVersion,
    metadata: {
      reviewRequired: status === "CandidateAvailable"
    },
    reason:
      status === "CandidateAvailable"
        ? `Trusted upstream version ${discoveredVersion} differs from reviewed catalog version ${input.catalogVersion}.`
        : `Reviewed catalog version ${input.catalogVersion} matches trusted upstream metadata.`,
    requiredActions:
      status === "CandidateAvailable"
        ? [
            "Review upstream release notes before updating the reviewed catalog.",
            "Update module fixtures, parser tests, license notices, and runtime pins before tenant recommendations can apply it."
          ]
        : ["No upstream catalog update candidate was found."],
    sourceKind: "ConfiguredOverride",
    sourceUrl: null,
    status,
    tenantId: input.tenantId,
    toolId: input.toolId,
    updateAvailable: status === "CandidateAvailable"
  };
}

const SESSION_SECRET = "test-session-secret";
const SAML_IDP_CERTIFICATE_FIXTURE = [
  "-----BEGIN CERTIFICATE-----",
  "MIIC",
  "A".repeat(180),
  "-----END CERTIFICATE-----"
].join("\n");

type InMemoryUser = User & {
  mfaSecret: string | null;
  password: string | null;
};

type InMemoryUserTokenPurpose =
  | "EmailVerification"
  | "Invite"
  | "PasswordReset";

type InMemoryUserToken = {
  consumedAt: string | null;
  expiresAt: string;
  purpose: InMemoryUserTokenPurpose;
  token: string;
  tokenHash: string;
  tokenId: string;
  userId: string;
};

type InMemoryRecoveryCode = {
  codeHash: string;
  consumedAt: string | null;
  plaintext: string;
  recoveryCodeId: string;
};

function now() {
  return new Date().toISOString();
}

function calculateNextRunAt(
  frequency: MissionSchedule["frequency"],
  from: Date
) {
  const next = new Date(from);

  if (frequency === "Daily") {
    next.setUTCDate(next.getUTCDate() + 1);
  } else if (frequency === "Weekly") {
    next.setUTCDate(next.getUTCDate() + 7);
  } else {
    next.setUTCMonth(next.getUTCMonth() + 1);
  }

  return next.toISOString();
}

