  function createUserToken(
    userId: string,
    purpose: InMemoryUserTokenPurpose,
    ttlMs = 60 * 60 * 1000
  ): InMemoryUserToken {
    const token = `${purpose.toLowerCase()}-${randomUUID()}`;
    const record: InMemoryUserToken = {
      consumedAt: null,
      expiresAt: new Date(Date.now() + ttlMs).toISOString(),
      purpose,
      token,
      tokenHash: hashSecret(token),
      tokenId: randomUUID(),
      userId
    };

    userTokens.set(record.tokenHash, record);

    return record;
  }

  function getValidUserToken(
    token: string,
    purpose: InMemoryUserTokenPurpose
  ): InMemoryUserToken {
    const record = userTokens.get(hashSecret(token));

    if (
      !record ||
      record.purpose !== purpose ||
      record.consumedAt ||
      Date.parse(record.expiresAt) <= Date.now()
    ) {
      throw new AppServiceError(
        "This link is invalid or has expired.",
        400,
        "invalid_token"
      );
    }

    return record;
  }

  function consumeUserToken(record: InMemoryUserToken) {
    userTokens.set(record.tokenHash, {
      ...record,
      consumedAt: now()
    });
  }

  function normalizeRecoveryCode(code: string) {
    return code.replace(/[^A-Za-z0-9]/gu, "").toUpperCase();
  }

  function generateRecoveryCodesForUser(userId: string) {
    const codes = Array.from({ length: 10 }, (_, index) => {
      const segment = (index + 1).toString().padStart(4, "0");
      return `TEST-CODE-${segment}-${userId.slice(0, 4).toUpperCase()}`;
    });

    mfaRecoveryCodesByUserId.set(
      userId,
      codes.map((plaintext) => ({
        codeHash: hashSecret(normalizeRecoveryCode(plaintext)),
        consumedAt: null,
        plaintext,
        recoveryCodeId: randomUUID()
      }))
    );

    return codes;
  }

  function assertReauthenticated(
    user: InMemoryUser,
    input: { password?: string; totpCode?: string }
  ) {
    const passwordOk = Boolean(
      input.password && input.password === user.password
    );
    const totpOk = Boolean(
      input.totpCode &&
      user.mfaSecret &&
      verifyTotp(user.mfaSecret, input.totpCode, Date.now(), { window: 1 })
    );

    if (!passwordOk && !totpOk) {
      throw new AppServiceError(
        "Re-authenticate with your password or a current code.",
        401,
        "reauth_required"
      );
    }
  }

