  function clientTenantList(parentTenantId: string) {
    return [...tenants.values()]
      .filter(
        (tenant) =>
          tenant.parentTenantId === parentTenantId && tenant.type === "Client"
      )
      .sort((left, right) => left.createdAt.localeCompare(right.createdAt));
  }

  function billingUsageForTenant(tenant: Tenant): BillingUsage {
    const measuredAt = now();
    const start = new Date();

    start.setUTCDate(1);
    start.setUTCHours(0, 0, 0, 0);

    const end = new Date(start);

    end.setUTCMonth(end.getUTCMonth() + 1);

    const quantities = new Map<string, number>([
      [
        "ValidatedAssets",
        [...assets.values()].filter(
          (asset) => asset.tenantId === tenant.tenantId
        ).length
      ],
      ["Identities", 0],
      [
        "ControlSources",
        [...controlSources.values()].filter(
          (controlSource) => controlSource.tenantId === tenant.tenantId
        ).length
      ],
      [
        "AIApplications",
        [...aiApplications.values()].filter(
          (aiApp) => aiApp.tenantId === tenant.tenantId
        ).length
      ],
      [
        "ValidationMissions",
        [...missions.values()].filter(
          (mission) => mission.tenantId === tenant.tenantId
        ).length
      ],
      [
        "ValidationRuns",
        [...missionRuns.values()].filter(
          (run) => run.tenantId === tenant.tenantId
        ).length
      ],
      ["RunnerMinutes", 0],
      [
        "EvidencePacks",
        [...evidencePacks.values()].filter(
          (pack) => pack.tenantId === tenant.tenantId
        ).length
      ],
      ["ClientTenants", clientTenantList(tenant.tenantId).length],
      [
        "APIUsage",
        [...auditEvents.values()].filter(
          (event) => event.tenantId === tenant.tenantId
        ).length
      ]
    ]);

    return {
      billingAccountId: tenant.billingAccountId,
      meteringPeriodEnd: end.toISOString(),
      meteringPeriodStart: start.toISOString(),
      meters: usageMeterDefinitions.map((definition) => ({
        ...definition,
        measuredAt,
        quantity: quantities.get(definition.meterName) ?? 0
      })),
      tenantId: tenant.tenantId
    };
  }

  function meterQuantity(usage: BillingUsage, meterName: UsageMeterName) {
    return (
      usage.meters.find((meter) => meter.meterName === meterName)?.quantity ?? 0
    );
  }

  function latestByCreatedAt<T extends { createdAt: string }>(items: T[]) {
    return items.sort((left, right) =>
      right.createdAt.localeCompare(left.createdAt)
    )[0];
  }

  function classifyClientPortfolioReadiness(input: {
    connectedIntegrations: number;
    criticalPaths: number;
    evidencePacks: number;
    highPaths: number;
    missingProofInputs: number;
    openRemediations: number;
    totalValidationRuns: number;
    unhealthyIntegrations: number;
    verifiedScopes: number;
  }): ClientPortfolioReadinessStatus {
    if (input.verifiedScopes === 0) {
      return "NeedsScope";
    }

    if (input.connectedIntegrations === 0) {
      return "NeedsIntegration";
    }

    if (input.totalValidationRuns === 0 && input.evidencePacks === 0) {
      return "NeedsValidation";
    }

    if (
      input.criticalPaths > 0 ||
      input.highPaths > 0 ||
      input.missingProofInputs > 0 ||
      input.openRemediations > 0 ||
      input.unhealthyIntegrations > 0
    ) {
      return "Attention";
    }

    return "Active";
  }

  function clientPortfolioSummary(tenant: Tenant): ClientPortfolioSummary {
    const tenantScopes = [...scopes.values()].filter(
      (scope) => scope.tenantId === tenant.tenantId
    );
    const tenantIntegrations = [...integrations.values()].filter(
      (integration) => integration.tenantId === tenant.tenantId
    );
    const tenantAttackPaths = [...attackPaths.values()].filter(
      (path) => path.attackPath.tenantId === tenant.tenantId
    );
    const tenantRemediations = [...remediations.values()].filter(
      (remediation) => remediation.tenantId === tenant.tenantId
    );
    const tenantReports = [...evidencePacks.values()].filter(
      (pack) => pack.tenantId === tenant.tenantId
    );
    const tenantRuns = [...missionRuns.values()].filter(
      (run) => run.tenantId === tenant.tenantId
    );
    const tenantSnapshots = [...snapshots.values()].filter(
      (snapshot) => snapshot.tenantId === tenant.tenantId
    );
    const usage = billingUsageForTenant(tenant);
    const latestReport = latestByCreatedAt(tenantReports);
    const latestRun = latestByCreatedAt(tenantRuns);
    const latestSnapshot = latestByCreatedAt(tenantSnapshots);
    const criticalPaths = tenantAttackPaths.filter(
      (path) =>
        path.attackPath.validationState !== "Fixed" &&
        path.attackPath.impactScore >= 90
    ).length;
    const highPaths = tenantAttackPaths.filter(
      (path) =>
        path.attackPath.validationState !== "Fixed" &&
        path.attackPath.impactScore >= 70 &&
        path.attackPath.impactScore < 90
    ).length;
    const openRemediations = tenantRemediations.filter((remediation) =>
      [
        "Open",
        "InProgress",
        "PartiallyFixed",
        "StillExposed",
        "Inconclusive",
        "Reopened",
        "ClosedWithoutEvidence"
      ].includes(remediation.status)
    ).length;
    const connectedIntegrations = tenantIntegrations.length;
    const unhealthyIntegrations = tenantIntegrations.filter((integration) =>
      ["Degraded", "Unhealthy"].includes(integration.healthStatus)
    ).length;
    const verifiedScopes = tenantScopes.filter(
      (scope) => scope.verificationStatus === "Verified"
    ).length;
    const missingProofInputs = [...missingSignals.values()].filter(
      (signal) =>
        signal.tenantId === tenant.tenantId &&
        [
          "NotConfigured",
          "RequiresIntegration",
          "RequiresVerifiedScope",
          "RequiresInternalRunner",
          "NotImplemented"
        ].includes(signal.status)
    ).length;

    return {
      branding:
        tenantBranding.get(tenant.tenantId) ?? defaultBranding(tenant.tenantId),
      coverage: {
        aiApplications: [...aiApplications.values()].filter(
          (aiApp) => aiApp.tenantId === tenant.tenantId
        ).length,
        connectedIntegrations,
        controlSources: [...controlSources.values()].filter(
          (controlSource) => controlSource.tenantId === tenant.tenantId
        ).length,
        healthyIntegrations: tenantIntegrations.filter(
          (integration) => integration.healthStatus === "Healthy"
        ).length,
        missingProofInputs,
        runners: runnerList(tenant.tenantId).length,
        totalScopes: tenantScopes.length,
        unhealthyIntegrations,
        verifiedScopes
      },
      latestActivity: {
        latestEvidencePackAt: latestReport?.createdAt ?? null,
        latestReportId: latestReport?.evidencePackId ?? null,
        latestSnapshotAt: latestSnapshot?.createdAt ?? null,
        latestSnapshotId: latestSnapshot?.snapshotId ?? null,
        latestValidationRunAt: latestRun?.createdAt ?? null
      },
      readinessStatus: classifyClientPortfolioReadiness({
        connectedIntegrations,
        criticalPaths,
        evidencePacks: meterQuantity(usage, "EvidencePacks"),
        highPaths,
        missingProofInputs,
        openRemediations,
        totalValidationRuns: meterQuantity(usage, "ValidationRuns"),
        unhealthyIntegrations,
        verifiedScopes
      }),
      risk: {
        criticalPaths,
        fixedPaths: tenantAttackPaths.filter(
          (path) => path.attackPath.validationState === "Fixed"
        ).length,
        highPaths,
        lowPaths: tenantAttackPaths.filter(
          (path) =>
            path.attackPath.validationState !== "Fixed" &&
            path.attackPath.impactScore < 40
        ).length,
        mediumPaths: tenantAttackPaths.filter(
          (path) =>
            path.attackPath.validationState !== "Fixed" &&
            path.attackPath.impactScore >= 40 &&
            path.attackPath.impactScore < 70
        ).length,
        openRemediations,
        verificationPending: tenantRemediations.filter(
          (remediation) => remediation.status === "VerificationPending"
        ).length
      },
      tenant,
      usage
    };
  }

  function clientPortfolioForContext(
    context: AuthenticatedContext
  ): MSSPClientPortfolio {
    requireMsspAdmin(context);

    if (context.tenant.type !== "MSSP") {
      throw new AppServiceError(
        "Only MSSP tenants can view the client portfolio.",
        400,
        "mssp_tenant_required"
      );
    }

    const clients = clientTenantList(context.tenant.tenantId).map((tenant) =>
      clientPortfolioSummary(tenant)
    );

    return {
      clients,
      generatedAt: now(),
      parentTenant: context.tenant,
      totals: {
        activeClients: clients.filter(
          (client) => client.readinessStatus === "Active"
        ).length,
        attentionClients: clients.filter(
          (client) => client.readinessStatus === "Attention"
        ).length,
        clientTenants: clients.length,
        evidencePacks: clients.reduce(
          (total, client) =>
            total + meterQuantity(client.usage, "EvidencePacks"),
          0
        ),
        missingProofInputs: clients.reduce(
          (total, client) => total + client.coverage.missingProofInputs,
          0
        ),
        needsIntegrationClients: clients.filter(
          (client) => client.readinessStatus === "NeedsIntegration"
        ).length,
        needsScopeClients: clients.filter(
          (client) => client.readinessStatus === "NeedsScope"
        ).length,
        needsValidationClients: clients.filter(
          (client) => client.readinessStatus === "NeedsValidation"
        ).length,
        openRemediations: clients.reduce(
          (total, client) => total + client.risk.openRemediations,
          0
        ),
        validationRuns: clients.reduce(
          (total, client) =>
            total + meterQuantity(client.usage, "ValidationRuns"),
          0
        ),
        verifiedScopes: clients.reduce(
          (total, client) => total + client.coverage.verifiedScopes,
          0
        ),
        shortTermAssessments: clients.reduce(
          (total, client) =>
            total + meterQuantity(client.usage, "ShortTermAssessments"),
          0
        )
      }
    };
  }

  function runnerList(tenantId: string) {
    return [...runners.values()]
      .filter((runner) => runner.tenantId === tenantId)
      .sort((left, right) => right.createdAt.localeCompare(left.createdAt));
  }

  function buildRunnerScopeConstraints(scope: Scope, ports: number[]) {
    if (scope.scopeType === "Domain" || scope.scopeType === "Subdomain") {
      return {
        approvedCidrs: [],
        approvedDnsSuffixes: [scope.value],
        approvedHostnames: [scope.value],
        approvedPorts: ports,
        forbidInternetEgress: false
      };
    }

    return {
      approvedCidrs: scope.scopeType === "IPRange" ? [scope.value] : [],
      approvedDnsSuffixes: [],
      approvedHostnames: scope.scopeType === "IPRange" ? [] : [scope.value],
      approvedPorts: ports,
      forbidInternetEgress: true
    };
  }

  function isRunnerTargetAllowed(scope: Scope, targetHost: string) {
    if (scope.scopeType === "InternalNetwork") {
      return true;
    }

    const normalizedTarget = targetHost.toLowerCase();
    const normalizedValue = scope.value.toLowerCase();

    return (
      normalizedTarget === normalizedValue ||
      normalizedTarget.endsWith(`.${normalizedValue}`)
    );
  }

  function signInMemoryRunnerEnvelope(
    envelope: Omit<RunnerTaskEnvelope, "signature">
  ): RunnerTaskEnvelope {
    return {
      ...envelope,
      signature: {
        algorithm: "EdDSA",
        digestSha256: `sha-${envelope.taskId}`,
        keyId: "test-runner-signing-key",
        nonce: envelope.taskId,
        signature: `signed-${envelope.taskId}`
      }
    };
  }

  async function createInMemoryRunnerTask(input: {
    context: AuthenticatedContext;
    envelopeInputs: Record<string, unknown>;
    moduleId: string;
    missionType?: ValidationMission["missionType"];
    policyProfile: string;
    ports: number[];
    runnerId: string;
    safetyLevel: ValidationRun["safetyLevel"];
    scopeId: string;
    target: Record<string, unknown>;
    targetHost: string;
    taskType: string;
    timeoutSeconds: number;
  }): Promise<RunnerTaskCreationResult> {
    requireScopeEditor(input.context);

    const runner = runners.get(input.runnerId);

    if (!runner || runner.tenantId !== input.context.tenant.tenantId) {
      throw new AppServiceError("Runner not found.", 404, "runner_not_found");
    }

    const scope = scopes.get(input.scopeId);

    if (!scope || scope.tenantId !== input.context.tenant.tenantId) {
      throw new AppServiceError("Scope not found.", 404, "scope_not_found");
    }

    if (scope.verificationStatus !== "Verified") {
      throw new AppServiceError(
        "Runner tasks require verified scope.",
        400,
        "verified_scope_required"
      );
    }

    if (!isRunnerTargetAllowed(scope, input.targetHost)) {
      throw new AppServiceError(
        "Runner target is outside the verified scope constraints.",
        400,
        "runner_scope_violation"
      );
    }

    const timestamp = now();
    const decision = await services.previewPolicyDecision(
      input.context,
      input.scopeId,
      {
        executionEnvironment: "InternalRunner",
        missionType: input.missionType ?? "ExposureValidation",
        requestedAction: {
          credentialTheft: false,
          destructive: false,
          persistence: false,
          realDataExfiltration: false,
          requiresInternalRunner: true,
          requiresTimeWindow: false,
          uncontrolledExploitChaining: false
        },
        safetyLevel: input.safetyLevel,
        target: {
          module: input.moduleId,
          ...input.target
        }
      }
    );
    const mission = await services.createMission(input.context, {
      missionType: input.missionType ?? "ExposureValidation",
      policyDecisionId: decision.policyDecisionId,
      policyProfile: input.policyProfile,
      safetyLevel: input.safetyLevel,
      scopeId: input.scopeId
    });
    const run: ValidationRun = {
      completedAt: null,
      createdAt: timestamp,
      errorSummary: null,
      evidenceIds: [],
      missionId: mission.missionId,
      moduleId: input.moduleId,
      outcome: null,
      policyDecisionId: decision.policyDecisionId,
      runId: randomUUID(),
      runnerId: input.runnerId,
      safetyLevel: input.safetyLevel,
      scopeId: input.scopeId,
      startedAt: null,
      status: "Queued",
      target: {
        ...input.target,
        timeoutSeconds: input.timeoutSeconds
      },
      tenantId: input.context.tenant.tenantId,
      techniqueIds: [],
      updatedAt: timestamp,
      validationState: null
    };
    const taskId = randomUUID();
    const expiresAt = new Date(Date.now() + 300_000).toISOString();
    const scopeConstraints = buildRunnerScopeConstraints(scope, input.ports);
    const envelope = signInMemoryRunnerEnvelope({
      artifactUpload: {
        artifactUploadUrl: `/api/v1/runners/${input.runnerId}/tasks/${taskId}/artifacts`,
        maxArtifactBytes: 1_000_000,
        resultCallbackUrl: `/api/v1/runners/${input.runnerId}/tasks/${taskId}/result`
      },
      executionEnvironment: "InternalRunner",
      expiresAt,
      inputs: input.envelopeInputs,
      issuedAt: timestamp,
      missionId: mission.missionId,
      moduleId: input.moduleId,
      runId: run.runId,
      runnerId: input.runnerId,
      safetyLevel: input.safetyLevel,
      scopeConstraints,
      scopeId: input.scopeId,
      target: input.target,
      taskId,
      tenantId: input.context.tenant.tenantId
    });
    const task: RunnerTaskRecord = {
      completedAt: null,
      createdAt: timestamp,
      envelope,
      errorSummary: null,
      expiresAt,
      inputs: envelope.inputs,
      issuedAt: timestamp,
      leasedAt: null,
      missionId: mission.missionId,
      moduleId: input.moduleId,
      redactedEvidenceIds: [],
      result: null,
      runId: run.runId,
      runnerId: input.runnerId,
      safetyLevel: input.safetyLevel,
      scopeConstraints,
      scopeId: input.scopeId,
      status: "Queued",
      target: envelope.target,
      taskId,
      taskType: input.taskType,
      tenantId: input.context.tenant.tenantId,
      updatedAt: timestamp
    };
    const queuedMission: ValidationMission = {
      ...mission,
      startedAt: timestamp,
      status: "Queued",
      updatedAt: timestamp
    };

    missions.set(queuedMission.missionId, queuedMission);
    missionRuns.set(run.runId, run);
    runnerTasks.set(taskId, task);

    return {
      envelope,
      mission: queuedMission,
      run,
      task
    };
  }

  function aiApplicationList(tenantId: string) {
    return [...aiApplications.values()]
      .filter((aiApp) => aiApp.tenantId === tenantId)
      .sort((left, right) => left.createdAt.localeCompare(right.createdAt));
  }

  function controlSourceList(tenantId: string) {
    return [...controlSources.values()]
      .filter((controlSource) => controlSource.tenantId === tenantId)
      .sort((left, right) => left.createdAt.localeCompare(right.createdAt));
  }

  function threatCatalogList(query: ThreatCatalogQuery) {
    return [...threatIntelItems.values()]
      .filter((item) => !query.kind || item.kind === query.kind)
      .filter((item) => !query.severity || item.severity === query.severity)
      .filter((item) => query.kev === undefined || item.kev === query.kev)
      .filter((item) => {
        if (!query.q) {
          return true;
        }
        const q = query.q.toLowerCase();
        return (
          item.title.toLowerCase().includes(q) ||
          item.canonicalKey.toLowerCase().includes(q) ||
          (item.iocValue?.toLowerCase().includes(q) ?? false) ||
          item.cveIds.some((cveId) => cveId.toLowerCase().includes(q))
        );
      })
      .sort((left, right) => right.lastSeenAt.localeCompare(left.lastSeenAt))
      .slice(0, query.limit ?? 50);
  }

  function threatAlertList(
    tenantId: string,
    status?: TenantThreatAlertStatus,
    limit = 100
  ) {
    return [...tenantThreatAlerts.values()]
      .filter(
        (alert) =>
          tenantThreatAlertTenants.get(alert.tenantThreatAlertId) === tenantId
      )
      .filter((alert) => !status || alert.status === status)
      .sort((left, right) => right.createdAt.localeCompare(left.createdAt))
      .slice(0, limit);
  }

  function requireContext(
    session: SessionClaims,
    requestedTenantId?: string
  ): AuthenticatedContext | null {
    const tenantId = requestedTenantId ?? session.defaultTenantId;
    const membership = membershipsForUser(session.userId).find(
      (candidate) => candidate.tenantId === tenantId
    );

    if (!membership) {
      return null;
    }

    const user = users.get(session.userId);
    const tenant = tenants.get(tenantId);

    if (!user || !tenant) {
      return null;
    }

    if (
      (session.authMethod === "password" || session.authMethod === "sso") &&
      (session.sessionVersion ?? 0) !==
        (sessionVersions.get(session.userId) ?? 0)
    ) {
      return null;
    }

    const ssoConfig = tenantSsoConfigs.get(tenantId);
    if (ssoConfig?.status === "Enabled" && ssoConfig.enforced) {
      if (session.authMethod === "system") {
        // System jobs are allowed to keep operating after SSO enforcement.
      } else if (
        session.authMethod !== "sso" ||
        session.defaultTenantId !== tenantId
      ) {
        return null;
      }
    }

    return {
      membership,
      session,
      tenant,
      user
    };
  }

