  it("enforces RBAC and tenant isolation on tenant and scope routes", async () => {
    const { services, state } = createInMemoryServices();
    const app = await buildApp({
      services,
      sessionSecret: SESSION_SECRET
    });

    const tenantA = await app.inject({
      method: "POST",
      url: "/api/v1/auth/signup",
      payload: {
        email: "owner-a@periscan.local",
        name: "Owner A",
        password: "owner-a-password",
        tenantName: "Tenant A"
      }
    });
    const ownerACookie = tenantA.cookies[0]!.value;

    const createScopeResponse = await app.inject({
      method: "POST",
      url: "/api/v1/scopes",
      cookies: {
        [SESSION_COOKIE_NAME]: ownerACookie
      },
      payload: {
        scopeType: "Domain",
        value: "example.com"
      }
    });

    const scopeId = createScopeResponse.json().scopeId as string;

    const inviteResponse = await app.inject({
      method: "POST",
      url: "/api/v1/tenants/current/invite",
      cookies: {
        [SESSION_COOKIE_NAME]: ownerACookie
      },
      payload: {
        email: "viewer@periscan.local",
        name: "Viewer User",
        role: "Viewer"
      }
    });

    expect(inviteResponse.statusCode).toBe(201);

    const viewerId = inviteResponse.json().user.userId as string;
    const tenantAId = tenantA.json().tenant.tenantId as string;
    const viewerCookie = await createSessionToken(
      {
        defaultTenantId: tenantAId,
        userId: viewerId
      },
      SESSION_SECRET
    );
    const evidenceId = randomUUID();
    const timestamp = now();
    state.evidenceArtifacts.set(evidenceId, {
      artifactType: "NormalizedEvidence",
      createdAt: timestamp,
      evidenceId,
      redactionStatus: "NotRequired",
      relatedEntityId: randomUUID(),
      relatedEntityType: "ValidationRun",
      sensitivityLevel: "High",
      sha256: `sha-${evidenceId}`,
      storageUri: `memory://${evidenceId}`,
      tenantId: tenantAId,
      updatedAt: timestamp
    });

    const viewerCreateScope = await app.inject({
      method: "POST",
      url: "/api/v1/scopes",
      cookies: {
        [SESSION_COOKIE_NAME]: viewerCookie
      },
      payload: {
        scopeType: "Domain",
        value: "viewer.example.com"
      }
    });

    expect(viewerCreateScope.statusCode).toBe(403);

    const viewerTrustSafety = await app.inject({
      method: "GET",
      url: "/api/v1/tenants/current/trust-safety",
      cookies: {
        [SESSION_COOKIE_NAME]: viewerCookie
      }
    });

    expect(viewerTrustSafety.statusCode).toBe(403);

    const viewerRedactEvidence = await app.inject({
      method: "POST",
      url: `/api/v1/evidence/${evidenceId}/redact`,
      cookies: {
        [SESSION_COOKIE_NAME]: viewerCookie
      }
    });

    expect(viewerRedactEvidence.statusCode).toBe(403);

    const ownerRedactEvidence = await app.inject({
      method: "POST",
      url: `/api/v1/evidence/${evidenceId}/redact`,
      cookies: {
        [SESSION_COOKIE_NAME]: ownerACookie
      }
    });

    expect(ownerRedactEvidence.statusCode).toBe(200);

    const tenantB = await app.inject({
      method: "POST",
      url: "/api/v1/auth/signup",
      payload: {
        email: "owner-b@periscan.local",
        name: "Owner B",
        password: "owner-b-password",
        tenantName: "Tenant B"
      }
    });

    const ownerBCookie = tenantB.cookies[0]!.value;
    const crossTenantScopeRead = await app.inject({
      method: "GET",
      url: `/api/v1/scopes/${scopeId}`,
      cookies: {
        [SESSION_COOKIE_NAME]: ownerBCookie
      }
    });

    expect(crossTenantScopeRead.statusCode).toBe(404);

    await app.close();
  });

  it("manages tenant OIDC SSO configuration through admin-only API routes", async () => {
    const { services } = createInMemoryServices();
    const app = await buildApp({
      services,
      sessionSecret: SESSION_SECRET
    });

    const signupResponse = await app.inject({
      method: "POST",
      payload: {
        email: "sso-owner@periscan.local",
        name: "SSO Owner",
        password: "sso-owner-password",
        tenantName: "SSO Tenant"
      },
      url: "/api/v1/auth/signup"
    });
    const ownerCookie = signupResponse.cookies[0]!.value;
    const tenantId = signupResponse.json().tenant.tenantId as string;

    const emptyResponse = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: ownerCookie
      },
      method: "GET",
      url: "/api/v1/tenants/current/sso"
    });

    expect(emptyResponse.statusCode).toBe(200);
    expect(emptyResponse.json()).toEqual({ config: null });

    const updateResponse = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: ownerCookie
      },
      method: "PUT",
      payload: {
        authorizationEndpoint: "https://idp.example.com/oauth2/v1/authorize",
        clientId: "periscan-client",
        clientSecret: "super-secret-oidc-client-secret",
        emailDomainAllowlist: ["Example.COM", "security.example.com"],
        enabled: true,
        enforced: false,
        issuerUrl: "https://idp.example.com/oauth2/default",
        jwksUri: "https://idp.example.com/oauth2/v1/keys",
        redirectUri: "https://app.periscan.example/auth/callback",
        scopes: ["openid", "email", "profile"],
        tokenEndpoint: "https://idp.example.com/oauth2/v1/token"
      },
      url: "/api/v1/tenants/current/sso"
    });

    expect(updateResponse.statusCode).toBe(200);
    expect(updateResponse.json()).toMatchObject({
      authorizationEndpoint: "https://idp.example.com/oauth2/v1/authorize",
      clientId: "periscan-client",
      clientSecretSet: true,
      emailDomainAllowlist: ["example.com", "security.example.com"],
      enforced: false,
      issuerUrl: "https://idp.example.com/oauth2/default",
      providerType: "OIDC",
      scopes: ["openid", "email", "profile"],
      status: "Enabled",
      tenantId
    });
    expect(JSON.stringify(updateResponse.json())).not.toContain(
      "super-secret-oidc-client-secret"
    );

    const readResponse = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: ownerCookie
      },
      method: "GET",
      url: "/api/v1/tenants/current/sso"
    });

    expect(readResponse.statusCode).toBe(200);
    expect(readResponse.json().config).toMatchObject({
      clientSecretSet: true,
      status: "Enabled"
    });

    const authUrlResponse = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: ownerCookie
      },
      method: "GET",
      url:
        "/api/v1/tenants/current/sso/authorization-url?" +
        new URLSearchParams({
          loginHint: "owner@example.com",
          nonce: "nonce-value-123",
          prompt: "select_account",
          state: "state-value-123"
        }).toString()
    });

    expect(authUrlResponse.statusCode).toBe(200);
    const authorizationUrl = new URL(
      authUrlResponse.json().authorizationUrl as string
    );
    expect(authorizationUrl.origin).toBe("https://idp.example.com");
    expect(authorizationUrl.searchParams.get("client_id")).toBe(
      "periscan-client"
    );
    expect(authorizationUrl.searchParams.get("response_type")).toBe("code");
    expect(authorizationUrl.searchParams.get("scope")).toBe(
      "openid email profile"
    );
    expect(authorizationUrl.searchParams.get("state")).toBe("state-value-123");
    expect(authorizationUrl.searchParams.get("nonce")).toBe("nonce-value-123");
    expect(authorizationUrl.searchParams.get("login_hint")).toBe(
      "owner@example.com"
    );
    expect(authorizationUrl.searchParams.get("prompt")).toBe("select_account");

    const inviteResponse = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: ownerCookie
      },
      method: "POST",
      payload: {
        email: "sso-viewer@periscan.local",
        name: "SSO Viewer",
        role: "Viewer"
      },
      url: "/api/v1/tenants/current/invite"
    });
    const viewerCookie = await createSessionToken(
      {
        authMethod: "sso",
        defaultTenantId: tenantId,
        userId: inviteResponse.json().user.userId as string
      },
      SESSION_SECRET
    );
    const viewerReadResponse = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: viewerCookie
      },
      method: "GET",
      url: "/api/v1/tenants/current/sso"
    });

    expect(viewerReadResponse.statusCode).toBe(403);

    const disableResponse = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: ownerCookie
      },
      method: "DELETE",
      url: "/api/v1/tenants/current/sso"
    });

    expect(disableResponse.statusCode).toBe(204);

    const disabledAuthUrlResponse = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: ownerCookie
      },
      method: "GET",
      url:
        "/api/v1/tenants/current/sso/authorization-url?" +
        new URLSearchParams({
          nonce: "nonce-value-456",
          state: "state-value-456"
        }).toString()
    });

    expect(disabledAuthUrlResponse.statusCode).toBe(400);
    expect(disabledAuthUrlResponse.json().code).toBe("sso_not_enabled");

    const auditResponse = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: ownerCookie
      },
      method: "GET",
      url: "/api/v1/audit-events?limit=100"
    });
    const ssoAuditActions = auditResponse
      .json()
      .items.map((event: AuditEvent) => event.action)
      .filter((action: string) => action.startsWith("sso_config."));

    expect(ssoAuditActions).toEqual([
      "sso_config.disabled",
      "sso_config.updated"
    ]);

    await app.close();
  });

  it("manages tenant SAML SSO configuration, metadata, and form callbacks", async () => {
    const { services } = createInMemoryServices();
    const app = await buildApp({
      services,
      sessionSecret: SESSION_SECRET
    });

    const signupResponse = await app.inject({
      method: "POST",
      payload: {
        email: "saml-owner@periscan.local",
        name: "SAML Owner",
        password: "saml-owner-password",
        tenantName: "SAML Tenant"
      },
      url: "/api/v1/auth/signup"
    });
    const ownerCookie = signupResponse.cookies[0]!.value;
    const tenantId = signupResponse.json().tenant.tenantId as string;

    const updateResponse = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: ownerCookie
      },
      method: "PUT",
      payload: {
        authorizationEndpoint: "https://idp.example.com/saml/sso",
        clientId: "https://api.periscan.example/saml/sp",
        emailDomainAllowlist: ["Periscan.LOCAL"],
        enabled: true,
        enforced: false,
        issuerUrl: "https://idp.example.com/saml",
        providerType: "SAML",
        redirectUri: "https://api.periscan.example/api/v1/auth/sso/callback",
        samlIdpCertificate: SAML_IDP_CERTIFICATE_FIXTURE
      },
      url: "/api/v1/tenants/current/sso"
    });

    expect(updateResponse.statusCode).toBe(200);
    expect(updateResponse.body).not.toContain(SAML_IDP_CERTIFICATE_FIXTURE);
    expect(updateResponse.json()).toMatchObject({
      authorizationEndpoint: "https://idp.example.com/saml/sso",
      clientId: "https://api.periscan.example/saml/sp",
      clientSecretSet: false,
      emailDomainAllowlist: ["periscan.local"],
      enforced: false,
      issuerUrl: "https://idp.example.com/saml",
      providerType: "SAML",
      samlIdpCertificateSet: true,
      samlNameIdFormat:
        "urn:oasis:names:tc:SAML:1.1:nameid-format:emailAddress",
      scopes: ["saml:nameid:emailAddress"],
      status: "Enabled",
      tenantId,
      tokenEndpoint: null
    });

    const readResponse = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: ownerCookie
      },
      method: "GET",
      url: "/api/v1/tenants/current/sso"
    });
    expect(readResponse.statusCode).toBe(200);
    expect(readResponse.json().config).toMatchObject({
      clientSecretSet: false,
      providerType: "SAML",
      samlIdpCertificateSet: true,
      status: "Enabled"
    });
    expect(JSON.stringify(readResponse.json())).not.toContain(
      SAML_IDP_CERTIFICATE_FIXTURE
    );

    const metadataResponse = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: ownerCookie
      },
      method: "GET",
      url: "/api/v1/tenants/current/sso/metadata"
    });
    expect(metadataResponse.statusCode).toBe(200);
    expect(metadataResponse.headers["content-type"]).toContain(
      "application/samlmetadata+xml"
    );
    expect(metadataResponse.body).toContain(
      'EntityDescriptor entityID="https://api.periscan.example/saml/sp"'
    );
    expect(metadataResponse.body).toContain(
      'AssertionConsumerService Location="https://api.periscan.example/api/v1/auth/sso/callback"'
    );

    const authUrlResponse = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: ownerCookie
      },
      method: "GET",
      url:
        "/api/v1/tenants/current/sso/authorization-url?" +
        new URLSearchParams({
          nonce: "nonce-saml-123",
          state: "state-saml-123"
        }).toString()
    });
    expect(authUrlResponse.statusCode).toBe(400);
    expect(authUrlResponse.json().code).toBe("sso_saml_start_required");

    const callbackResponse = await app.inject({
      headers: {
        "content-type": "application/x-www-form-urlencoded"
      },
      method: "POST",
      payload: new URLSearchParams({
        RelayState: `state-${randomUUID()}-${randomUUID()}`,
        SAMLResponse: "invalid-saml-response"
      }).toString(),
      url: "/api/v1/auth/sso/callback"
    });
    expect(callbackResponse.statusCode).toBe(401);
    expect(callbackResponse.json().code).toBe("sso_state_invalid");

    await app.close();
  });

