  it("long-polls mission runs until terminal status or timeout [P20-3]", async () => {
    const { services, state } = createInMemoryServices();
    const app = await buildApp({
      services,
      sessionSecret: SESSION_SECRET
    });

    const signupResponse = await app.inject({
      method: "POST",
      url: "/api/v1/auth/signup",
      payload: {
        email: "mission-wait@periscan.local",
        name: "Mission Wait Owner",
        password: "mission-wait-password",
        tenantName: "Mission Wait Tenant"
      }
    });
    expect(signupResponse.statusCode).toBe(201);
    const cookie = signupResponse.cookies[0]!.value;
    const tenantId = signupResponse.json().tenant.tenantId as string;
    const timestamp = now();
    const missionId = randomUUID();
    const runId = randomUUID();
    const scopeId = randomUUID();

    state.missionRuns.set(runId, {
      completedAt: null,
      createdAt: timestamp,
      errorSummary: null,
      evidenceIds: [],
      missionId,
      moduleId: "nuclei.external_exposure_safe",
      outcome: null,
      policyDecisionId: null,
      runId,
      runnerId: null,
      safetyLevel: "PassiveReadOnly",
      scopeId,
      startedAt: null,
      status: "Queued",
      target: { hostname: "wait.example.com" },
      techniqueIds: [],
      tenantId,
      updatedAt: timestamp,
      validationState: null
    });

    const timeoutResponse = await app.inject({
      method: "GET",
      url: `/api/v1/missions/${missionId}/runs/${runId}/wait?timeoutMs=100`,
      cookies: {
        [SESSION_COOKIE_NAME]: cookie
      }
    });
    expect(timeoutResponse.statusCode).toBe(408);
    expect(timeoutResponse.json()).toMatchObject({
      missionId,
      runId,
      status: "Queued",
      tenantId
    });
    expect(timeoutResponse.headers["retry-after"]).toBe("1");

    const waitPromise = app.inject({
      method: "GET",
      url: `/api/v1/missions/${missionId}/runs/${runId}/wait?timeoutMs=2000`,
      cookies: {
        [SESSION_COOKIE_NAME]: cookie
      }
    });
    await new Promise((resolve) => {
      setTimeout(resolve, 80);
    });
    const current = state.missionRuns.get(runId)!;
    state.missionRuns.set(runId, {
      ...current,
      completedAt: now(),
      outcome: "NoExposure",
      status: "Completed",
      updatedAt: now(),
      validationState: "Validated"
    });
    const completedResponse = await waitPromise;
    expect(completedResponse.statusCode).toBe(200);
    expect(completedResponse.json()).toMatchObject({
      missionId,
      runId,
      status: "Completed",
      tenantId
    });

    const alreadyTerminalResponse = await app.inject({
      method: "GET",
      url: `/api/v1/missions/${missionId}/runs/${runId}/wait?timeoutMs=5000`,
      cookies: {
        [SESSION_COOKIE_NAME]: cookie
      }
    });
    expect(alreadyTerminalResponse.statusCode).toBe(200);
    expect(alreadyTerminalResponse.json().status).toBe("Completed");

    const overCapResponse = await app.inject({
      method: "GET",
      url: `/api/v1/missions/${missionId}/runs/${runId}/wait?timeoutMs=60001`,
      cookies: {
        [SESSION_COOKIE_NAME]: cookie
      }
    });
    expect(overCapResponse.statusCode).toBe(400);

    const otherTenantSignup = await app.inject({
      method: "POST",
      url: "/api/v1/auth/signup",
      payload: {
        email: "mission-wait-other@periscan.local",
        name: "Other Wait Owner",
        password: "mission-wait-other-password",
        tenantName: "Other Wait Tenant"
      }
    });
    const otherCookie = otherTenantSignup.cookies[0]!.value;
    const crossTenantWaitResponse = await app.inject({
      method: "GET",
      url: `/api/v1/missions/${missionId}/runs/${runId}/wait?timeoutMs=100`,
      cookies: {
        [SESSION_COOKIE_NAME]: otherCookie
      }
    });
    expect(crossTenantWaitResponse.statusCode).toBe(404);

    const missingRunResponse = await app.inject({
      method: "GET",
      url: `/api/v1/missions/${missionId}/runs/${randomUUID()}/wait?timeoutMs=100`,
      cookies: {
        [SESSION_COOKIE_NAME]: cookie
      }
    });
    expect(missingRunResponse.statusCode).toBe(404);

    await app.close();
  });

