  it("recommends operator missions and generates evidence-grounded summaries through the API", async () => {
    const { services, state } = createInMemoryServices();
    const app = await buildApp({
      services,
      sessionSecret: SESSION_SECRET
    });

    const signupResponse = await app.inject({
      method: "POST",
      payload: {
        email: "operators@periscan.local",
        name: "Operators Tester",
        password: "periscan-operators-password",
        tenantName: "Operators Tenant"
      },
      url: "/api/v1/auth/signup"
    });
    const cookie = signupResponse.cookies[0]!.value;
    const tenantId = signupResponse.json().tenant.tenantId as string;

    const scopeResponse = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: cookie
      },
      method: "POST",
      payload: {
        scopeType: "Domain",
        value: "operators.example.com"
      },
      url: "/api/v1/scopes"
    });
    const scopeId = scopeResponse.json().scopeId as string;

    await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: cookie
      },
      method: "POST",
      payload: {
        devModeManual: true
      },
      url: `/api/v1/scopes/${scopeId}/verify`
    });

    const evidenceId = randomUUID();
    const pathId = randomUUID();
    const timestamp = now();

    state.evidenceArtifacts.set(evidenceId, {
      artifactType: "NormalizedEvidence",
      createdAt: timestamp,
      evidenceId,
      redactionStatus: "Redacted",
      relatedEntityId: pathId,
      relatedEntityType: "AttackPath",
      sensitivityLevel: "Moderate",
      sha256: "sha-operator-evidence",
      storageUri: "memory://operator-evidence.json",
      tenantId,
      updatedAt: timestamp
    });
    state.attackPaths.set(pathId, {
      attackPath: {
        confidence: 0.9,
        createdAt: timestamp,
        entryNodeId: randomUUID(),
        evidenceBasis: "Heuristic",
        evidenceIds: [evidenceId],
        impactNodeId: randomUUID(),
        impactScore: 90,
        name: "Repository secret to production role",
        pathBreakers: [],
        pathEdges: [],
        pathId,
        pathNodes: [],
        tenantId,
        updatedAt: timestamp,
        validationState: "Validated"
      },
      risk: {
        band: "Critical",
        factors: [],
        score: 90,
        summary: "Validated critical path."
      }
    });

    const operatorsResponse = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: cookie
      },
      method: "GET",
      url: "/api/v1/operators"
    });

    expect(operatorsResponse.statusCode).toBe(200);
    expect(operatorsResponse.json().items).toHaveLength(6);

    const recommendationsResponse = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: cookie
      },
      method: "GET",
      url: "/api/v1/operator-recommendations"
    });

    expect(recommendationsResponse.statusCode).toBe(200);
    const redTeamRecommendation = recommendationsResponse
      .json()
      .items.find(
        (item: OperatorRecommendation) =>
          item.operatorType === "RedTeamOperator"
      ) as OperatorRecommendation;

    expect(redTeamRecommendation.evidenceIds).toContain(evidenceId);
    expect(redTeamRecommendation.uncertainty).toBe("Low");
    expect(redTeamRecommendation.missionPlan.approvalRequired).toBe(true);

    const approveResponse = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: cookie
      },
      method: "POST",
      url: `/api/v1/operator-recommendations/${redTeamRecommendation.recommendationId}/approve`
    });

    expect(approveResponse.statusCode).toBe(201);
    expect(approveResponse.json().recommendation.status).toBe("Approved");
    expect(approveResponse.json().mission.status).toBe("Draft");
    expect(approveResponse.json().decision.outcome).toBe("RequiresApproval");

    // P11-4: generate path persists proposals; approve marks durable status.
    const persistedListAfterGenerate = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: cookie
      },
      method: "GET",
      url: "/api/v1/operators/recommendations"
    });
    expect(persistedListAfterGenerate.statusCode).toBe(200);
    const persistedItems = persistedListAfterGenerate.json()
      .items as OperatorRecommendationRecord[];
    expect(persistedItems.length).toBeGreaterThan(0);
    expect(
      persistedItems.some(
        (row) =>
          row.payload.recommendationId ===
            redTeamRecommendation.recommendationId &&
          row.status === "Approved"
      )
    ).toBe(true);

    const createPersistedResponse = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: cookie
      },
      method: "POST",
      payload: {
        payload: {
          recommendationId: "oprec_manual_test",
          title: "Manual proposal"
        },
        scopeId,
        status: "Proposed"
      },
      url: "/api/v1/operators/recommendations"
    });
    expect(createPersistedResponse.statusCode).toBe(201);
    expect(createPersistedResponse.json().tenantId).toBe(tenantId);
    expect(createPersistedResponse.json().scopeId).toBe(scopeId);
    expect(createPersistedResponse.json().status).toBe("Proposed");
    expect(createPersistedResponse.json().payload.title).toBe(
      "Manual proposal"
    );

    const persistedListAfterCreate = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: cookie
      },
      method: "GET",
      url: "/api/v1/operators/recommendations"
    });
    expect(persistedListAfterCreate.statusCode).toBe(200);
    expect(
      (
        persistedListAfterCreate.json().items as OperatorRecommendationRecord[]
      ).some(
        (row) => row.payload.recommendationId === "oprec_manual_test"
      )
    ).toBe(true);

    const summaryResponse = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: cookie
      },
      method: "POST",
      payload: {
        evidenceIds: [evidenceId],
        useCase: "ExecutiveSummary"
      },
      url: "/api/v1/evidence-summaries"
    });

    expect(summaryResponse.statusCode).toBe(201);
    expect(summaryResponse.json().evidenceIds).toContain(evidenceId);
    expect(summaryResponse.json().claims[0].evidenceIds).toContain(evidenceId);
    expect(JSON.stringify(summaryResponse.json())).not.toContain(
      "secret-value"
    );

    const insufficientSummaryResponse = await app.inject({
      cookies: {
        [SESSION_COOKIE_NAME]: cookie
      },
      method: "POST",
      payload: {
        evidenceIds: [],
        useCase: "AttackPathExplanation"
      },
      url: "/api/v1/evidence-summaries"
    });

    expect(insufficientSummaryResponse.statusCode).toBe(201);
    expect(insufficientSummaryResponse.json().claims).toHaveLength(0);
    expect(insufficientSummaryResponse.json().warnings[0]).toMatch(
      /No tenant-authorized evidence/i
    );

    await app.close();
  });

